per_hop.query:
SELECT ?series WHERE {
  ?series dbo:creator dbr:Hilarie_Ross_Burton ;
          dbo:network dbr:The_WB ;
          rdf:type dbo:TelevisionSeries .
}

SELECT ?actress WHERE {
  dbr:Grace,_Replaced dbo:starring ?actress .
}

SELECT ?actress ?series WHERE {
  ?series dbo:creator dbr:Hilarie_Ross_Burton ;
          dbo:network dbr:The_WB ;
          rdf:type dbo:TelevisionSeries .
  ?episode dbo:series ?series .
  ?episode dbo:guestStar ?actress .
  VALUES ?actress { <list_of_actresses_from_Grace_Replaced> }
}
